-- DATA ONLY. The corridor.centerline_m column and the conflate_point body
-- that reads it both live in 001-init.sql, deliberately and not here.
--
-- 001 is marked repeatable, so it re-applies whenever it is edited. If the
-- function lived in this file instead, any later edit to 001 would restore
-- the fraction-times-total_miles body and silently reintroduce the
-- systematic bias - with this file already recorded as applied, so nothing
-- would put it back. Schema and functions belong in the file that owns
-- them; this one carries only the geometry and the measured offsets.

CREATE TABLE IF NOT EXISTS corridor_geom_load (
  route    text    NOT NULL,
  part_no  integer NOT NULL,
  chunk    text    NOT NULL,
  PRIMARY KEY (route, part_no)
);

COMMENT ON TABLE corridor_geom_load IS
  'Staging for the chunked centerline load. The RDS Data API caps SQL statement size well below a 350 KB LINESTRINGM, so the geometry arrives in parts and is assembled with string_agg. Safe to truncate.';

