-- Assemble, then write both representations from the same source.
WITH ewkt AS (
  SELECT 'SRID=4326;LINESTRINGM(' ||
         string_agg(chunk, ',' ORDER BY part_no) || ')' AS t
  FROM corridor_geom_load
  WHERE route = 'I-40'
)
INSERT INTO corridor (route, description, centerline, centerline_m,
                      buffer_meters, verified, total_miles)
SELECT
  'I-40',
  'I-40 mainline, western AZ border to eastern OK border',
  ST_Force2D(ST_GeomFromEWKT(ewkt.t))::geography,
  ST_GeomFromEWKT(ewkt.t),
  1600,
  -- Geometry tripwire, and EARNED rather than asserted: this is written true
  -- only when the landmark check passed on the data being loaded. It is what
  -- probe.py and strip_export.py read to decide whether positions may be
  -- published, so a bad fetch must not be able to set it.
  true,
  1240.957
FROM ewkt
-- EVERY COLUMN THIS FILE SETS IS ALSO UPDATED HERE. The list used to omit
-- verified, description and buffer_meters, which made this repeatable
-- migration bring the row only PARTLY up to the file's state: a corridor
-- loaded once as unverified stayed unverified forever, no matter what the
-- landmark check said on later runs.
--
-- That is not cosmetic. verified is the publishability tripwire, and
-- it went out of step with reference/corridor.json - the JSON said true and
-- the database said false, for the same geometry from the same generator. The
-- deployed pipeline reads the database, so it would have withheld positions
-- the offline tools were happy to publish. A tripwire that disagrees with
-- itself is worse than none.
ON CONFLICT (route) DO UPDATE SET
  description   = EXCLUDED.description,
  centerline    = EXCLUDED.centerline,
  centerline_m  = EXCLUDED.centerline_m,
  buffer_meters = EXCLUDED.buffer_meters,
  verified      = EXCLUDED.verified,
  total_miles   = EXCLUDED.total_miles,
  updated_at    = now();

-- Measured per-state extents replace the config's rounded ones.
--
-- These numbers move by less than half a mile, which is exactly why they
-- matter: the state line is where cross-state dedup either works or
-- silently does not. With measured values the identity is exact -
-- AZ MP 359.349 and NM MP 0 resolve to the same corridor measure.
--
-- NOTE this changes what counts as a valid milepost. AZ MP 359.5 is now out
-- of range and milepost_to_measure returns NULL for it, which is correct
-- (an out-of-range milepost is not clamped). scripts/db.sh and tests/test_lrs.py
-- both used to hardcode that literal and now read the boundary out of this
-- table instead.
--
-- verified is inserted FALSE here and computed at the END of this file, once
-- segment geometry exists to compute it from. It means something different
-- from corridor.verified: that this state's boundary has been checked
-- GEOMETRICALLY rather than trusted from the offset arithmetic above.
INSERT INTO state_segment (route, state, state_mp_min, state_mp_max,
                           corridor_offset, verified)
VALUES ('I-40', 'AZ', 0.000, 359.347, 0.000, false)
ON CONFLICT (route, state) DO UPDATE SET
  state_mp_min    = EXCLUDED.state_mp_min,
  state_mp_max    = EXCLUDED.state_mp_max,
  corridor_offset = EXCLUDED.corridor_offset;
INSERT INTO state_segment (route, state, state_mp_min, state_mp_max,
                           corridor_offset, verified)
VALUES ('I-40', 'NM', 0.000, 373.530, 359.347, false)
ON CONFLICT (route, state) DO UPDATE SET
  state_mp_min    = EXCLUDED.state_mp_min,
  state_mp_max    = EXCLUDED.state_mp_max,
  corridor_offset = EXCLUDED.corridor_offset;
INSERT INTO state_segment (route, state, state_mp_min, state_mp_max,
                           corridor_offset, verified)
VALUES ('I-40', 'TX', 0.000, 177.141, 732.877, false)
ON CONFLICT (route, state) DO UPDATE SET
  state_mp_min    = EXCLUDED.state_mp_min,
  state_mp_max    = EXCLUDED.state_mp_max,
  corridor_offset = EXCLUDED.corridor_offset;
INSERT INTO state_segment (route, state, state_mp_min, state_mp_max,
                           corridor_offset, verified)
VALUES ('I-40', 'OK', 0.000, 330.939, 910.018, false)
ON CONFLICT (route, state) DO UPDATE SET
  state_mp_min    = EXCLUDED.state_mp_min,
  state_mp_max    = EXCLUDED.state_mp_max,
  corridor_offset = EXCLUDED.corridor_offset;

-- Per-state segment geometry, DERIVED rather than shipped.
--
-- state_segment.segment is what lets a state boundary be checked
-- GEOMETRICALLY instead of trusted from the offset arithmetic, which is what
-- state_segment.verified means. It was NULL until now, so the identity rested
-- entirely on numbers we wrote being compared against numbers we wrote.
--
-- ST_LocateBetween cuts the corridor at two measures, so each segment comes
-- OUT OF centerline_m rather than being loaded separately. That is the point:
-- four more geometries would double the size of this file, and - worse - they
-- could drift from the centerline they are supposed to describe. Derived,
-- they cannot.
--
-- ST_LocateBetween returns a collection, so extract the linestrings (type 2)
-- and merge them. Each state's measure range is contiguous in the corridor,
-- so the merge yields ONE LineString - which the verified test below asserts
-- rather than assumes, because a MULTILINESTRING would mean the corridor has
-- a hole in it and the geography(LineString) column would reject it anyway.
WITH derived AS (
  SELECT s.state,
         ST_LineMerge(ST_CollectionExtract(
           ST_LocateBetween(
             c.centerline_m,
             s.corridor_offset,
             s.corridor_offset + (s.state_mp_max - s.state_mp_min)), 2)) AS geom
  FROM state_segment s
  JOIN corridor c ON c.route = s.route
  WHERE s.route = 'I-40'
)
UPDATE state_segment s
SET segment  = ST_Force2D(d.geom)::geography,
    -- EARNED, like corridor.verified: computed from the geometry, not set.
    --
    -- The length tolerance is 1% of the state's milepost span, not an absolute
    -- figure. Geodesic chord length is ALWAYS shorter than LRS mileage - a
    -- straight line between vertices cannot be longer than the curve through
    -- them - and the shortfall scales with length and curvature. Measured, it
    -- is 0.15% to 0.21% per state (0.36 to 0.71 mi), so 1% passes comfortably
    -- while still catching the failure that matters: a state whose measure
    -- range is wrong is out by tens of miles, not tenths.
    verified = (
      d.geom IS NOT NULL
      AND GeometryType(d.geom) = 'LINESTRING'
      AND ABS(ST_Length(ST_Force2D(d.geom)::geography) / 1609.344
              - (s.state_mp_max - s.state_mp_min))
          < 0.01 * (s.state_mp_max - s.state_mp_min)
    )
FROM derived d
WHERE s.route = 'I-40' AND s.state = d.state;

-- Nothing below this point. conflate_point is defined in 001-init.sql and
-- already prefers centerline_m, so loading the geometry above is all that is
-- needed to switch conflation off the biased fraction path. Verify with:
--   npm run db-geometry && npm run db-landmarks

